import GLTFKit2
import SceneKit
import XCTest
@testable import AvatarKit

/// `catalog.json` is generated by `Tools/build-assets.mjs`; these check that it agrees
/// with the files next to it and that every part really fits the body's skeleton.
final class AvatarCatalogTests: XCTestCase {

    private var catalog: AvatarCatalog!

    override func setUpWithError() throws {
        catalog = try AvatarCatalog.bundled()
    }

    func test_everyReferencedFileExists() {
        let files = catalog.bodies.map(\.file) + catalog.items.map(\.file) + catalog.moves.compactMap(\.file)
        for file in files {
            XCTAssertTrue(FileManager.default.fileExists(atPath: catalog.url(for: file).path), file)
        }
    }

    func test_everyBodyHasTheNormalType() {
        XCTAssertFalse(catalog.bodies.isEmpty)
        for body in catalog.bodies {
            XCTAssertTrue(body.bodyTypes.contains(.normal), body.id)
        }
        XCTAssertEqual(catalog.genders.count, Set(catalog.genders).count)
    }

    func test_itemIDsAreUnique() {
        let ids = catalog.items.map(\.id)
        XCTAssertEqual(ids.count, Set(ids).count)
    }

    func test_defaultsUseItemsForTheirGender() {
        for gender in catalog.genders {
            let config = catalog.defaultConfig(for: gender)
            XCTAssertEqual(config.gender, gender)
            XCTAssertTrue(catalog.bodyTypes(for: gender).contains(config.bodyType), gender.rawValue)
            for (slot, selection) in config.items {
                let item = catalog.item(id: selection.itemID)
                XCTAssertEqual(item?.slot, slot, selection.itemID)
                XCTAssertEqual(item?.genders.contains(gender), true, selection.itemID)
            }
        }
    }

    func test_onlyTheWaveIsGeneratedInCode() {
        for asset in catalog.moves {
            let isGenerated = asset.file == nil || asset.clip == nil
            XCTAssertEqual(isGenerated, asset.move == .wave, asset.move.rawValue)
        }
    }

    func test_everyClipExistsInItsFile() async throws {
        for asset in catalog.moves {
            guard let file = asset.file, let clip = asset.clip else { continue }
            let gltf = try await AvatarAssetCache.shared.asset(at: catalog.url(for: file))
            XCTAssertTrue(gltf.animations.contains { $0.name == clip }, "\(clip) in \(file)")
        }
    }

    func test_tintedMaterialsHaveALuminance() {
        let materials = catalog.items.flatMap { $0.tintMaterials + $0.skinMaterials }
            + catalog.bodies.flatMap { $0.skinMaterials + $0.hairMaterials }
        for material in Set(materials) {
            XCTAssertNotNil(catalog.materialLuminance[material], material)
        }
    }

    /// Body types are morph targets: the body has one per listed type (besides `normal`),
    /// and every item that follows the body has the same ones, so it keeps fitting.
    @MainActor
    func test_bodyTypesAreMorphTargetsOfBodyAndItems() async throws {
        for body in catalog.bodies {
            let expected = Set(body.bodyTypes.filter { $0 != .normal }.map(\.rawValue))
            let container = try await AvatarAssetCache.shared.nodes(at: catalog.url(for: body.file))
            for node in container.childNodes(passingTest: { node, _ in node.geometry != nil }) {
                XCTAssertEqual(Set(node.morpher?.targets.compactMap(\.name) ?? []), expected, "\(body.id) \(node.name ?? "")")
            }
            for item in catalog.items where item.genders.contains(body.gender) {
                let part = try await AvatarAssetCache.shared.nodes(at: catalog.url(for: item.file))
                for node in part.childNodes(passingTest: { node, _ in node.morpher != nil }) {
                    XCTAssertEqual(Set(node.morpher?.targets.compactMap(\.name) ?? []), expected, item.id)
                }
            }
        }
    }

    /// Every item's skinned meshes must end up driven by the body's own bones.
    /// Guards against duplicate skeletons in merged files, which loaders rename (`pelvis_1`).
    @MainActor
    func test_everyItemBindsToTheBodySkeleton() async throws {
        for body in catalog.bodies {
            let container = try await AvatarAssetCache.shared.nodes(at: catalog.url(for: body.file))
            let rig = try AvatarRig(container: container, names: catalog.rig, file: body.file)
            let bodyBones = Set(container.childNodes { node, _ in node.skinner != nil }
                .flatMap { $0.skinner?.bones ?? [] }
                .map(ObjectIdentifier.init))

            for item in catalog.items where item.genders.contains(body.gender) {
                let part = try await AvatarAssetCache.shared.nodes(at: catalog.url(for: item.file))
                var originalBones: [String: [String?]] = [:]
                for node in part.childNodes(passingTest: { node, _ in node.skinner != nil }) {
                    originalBones[node.name ?? ""] = node.skinner?.bones.map(\.name)
                }

                let attached = rig.attach(partRoot: part)
                let skinned = attached.flatMap { [$0] + $0.childNodes }.filter { $0.skinner != nil }
                XCTAssertEqual(skinned.count, originalBones.count, item.id)
                for node in skinned {
                    let bones = node.skinner?.bones ?? []
                    XCTAssertTrue(bones.allSatisfy { bodyBones.contains(ObjectIdentifier($0)) }, "\(item.id) on \(body.id)")
                    // Same names in the same order: no bone fell back to the hips.
                    XCTAssertEqual(bones.map(\.name), originalBones[node.name ?? ""], "\(item.id) \(node.name ?? "")")
                }
                attached.forEach { $0.removeFromParentNode() }
            }
        }
    }

    @MainActor
    func test_waveBuildsForEveryBody() async throws {
        for body in catalog.bodies {
            let container = try await AvatarAssetCache.shared.nodes(at: catalog.url(for: body.file))
            let rig = try AvatarRig(container: container, names: catalog.rig, file: body.file)
            XCTAssertNotNil(AvatarWaveBuilder.animation(for: rig), body.id)
        }
    }
}
